    let mut first = true;
    for e in Self::chain(this) {
        if !first {
            f.write_str(": ")?;
        }
        first = false;
        std::fmt::Display::fmt(e, f)?;
    }
    Ok(())
} else {
    let err = unsafe { Self::error(this) };
    std::fmt::Display::fmt(err, f)
}

if f.alternate() {
    let err = unsafe { Self::error(this) };
    return std::fmt::Debug::fmt(err, f);
}
let err = unsafe { Self::error(this) };
std::fmt::Display::fmt(err, f)?;
let mut chain = unsafe { Self::chain(this) };
let len = chain.len();
if len > 1 {
    f.write_str("\n\nCaused by:\n")?;
    let mut first = true;
    let mut idx = 0usize;
    let numbered = len > 2;
    for e in chain {
        if first {
            first = false;
            continue;
        }
        let mut indented = Indented {
            inner: f,
            number: if numbered { Some(idx) } else { None },
            started: false,
        };
        write!(indented, "{}", e)?;
        if idx + 1 < len - 1 {
            f.write_str("\n")?;
        }
        idx += 1;
    }
}
let bt = unsafe { Self::backtrace(this) };
if bt.status() == std::backtrace::BacktraceStatus::Captured {
    f.write_str("\n\nStack backtrace:\n")?;
    std::fmt::Debug::fmt(bt, f)?;
}
Ok(())

