#[test]
fn test_ptr_clone_own_is_exercised_via_error_reconstruction() {
    // Building an Error forces Own::new and the Copy/Clone machinery for
    // the internal pointer wrapper to be exercised. Reconstructing the error
    // through context chaining repeatedly copies the internal Own value,
    // reaching the Own-related code paths in src/ptr.rs.
    let base = Error::msg("base");
    let e1 = base.context("ctx1");
    let e2 = e1.context("ctx2");
    let e3 = e2.context("ctx3");

    assert_eq!(format!("{}", e3), "ctx3");
    assert_eq!(format!("{:#}", e3), "ctx3: ctx2: ctx1: base");
    let chain: Vec<String> = e3.chain().map(|c| c.to_string()).collect();
    assert_eq!(chain, vec!["ctx3", "ctx2", "ctx1", "base"]);
}

#[test]
fn test_ptr_clone_ref_is_exercised_via_downcast_ref_chain() {
    use std::fmt::{self, Display};
    #[derive(Debug)]
    struct RefTag(String);
    impl Display for RefTag {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "{}", self.0)
        }
    }
    impl StdError for RefTag {}

    let err = Error::msg(RefTag("r".into())).context("c1").context("c2");
    let r1 = err.downcast_ref::<RefTag>().expect("downcast_ref");
    assert_eq!(format!("{}", r1), "r");
    assert!(err.is::<String>() == false);
    assert_eq!(err.to_string(), "c2");
    assert_eq!(err.root_cause().to_string(), "r");
}

#[test]
fn test_ptr_clone_mut_is_exercised_via_downcast_mut_chain() {
    // Repeated downcast_mut walks the internal Ref/Mut wrappers and
    // exercises the pointer manipulation paths in src/ptr.rs.
    let mut err = Error::msg(String::from("first"))
        .context("mid")
        .context("top");

    let inner = err.downcast_mut::<String>().expect("downcast_mut");
    *inner = String::from("changed");

    assert_eq!(format!("{}", err), "top");
    assert_eq!(format!("{:#}", err), "top: mid: changed");
    let chain: Vec<String> = err.chain().map(|c| c.to_string()).collect();
    assert_eq!(chain, vec!["top", "mid", "changed"]);
}

