#[test]
fn test_error_msg_display_and_chain_stability() {
    // Repeated formatting forces the internal ErrorImpl pointer wrappers to be
    // traversed multiple times through the public Display/Debug paths.
    let err = Error::msg("base");
    let err = err.context("first").context("second").context("third");

    assert_eq!(format!("{}", err), "third");
    assert_eq!(format!("{:#}", err), "third: second: first: base");

    let chain: Vec<String> = err.chain().map(|e| e.to_string()).collect();
    assert_eq!(chain, vec!["third", "second", "first", "base"]);
