#[test]
fn test_error_downcast_ref_idempotent_across_chain() {
    use std::fmt::{self, Display};

    #[derive(Debug)]
    struct Tag(&'static str);

    impl Display for Tag {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            write!(f, "{}", self.0)
        }
    }
    impl StdError for Tag {}

    let inner = Error::msg(Tag("leaf"));
    let err = inner.context("mid").context("top");

    // Downcast must succeed on the leaf even after multiple contexts.
    assert!(err.is::<Tag>());
    let a = err.downcast_ref::<Tag>().expect("first downcast");
    assert_eq!(a.0, "leaf");

    // Repeating the operation proves the Ref pointer handling stays stable.
    let b = err.downcast_ref::<Tag>().expect("second downcast");
    assert_eq!(b.0, "leaf");
    assert_eq!(format!("{}", err), "top");
}

#[test]
fn test_error_context_with_owned_string_and_display_alt() {
    let leaf = Error::msg(String::from("leaf_owned"));
    let mid = leaf.context(String::from("mid_owned"));
    let top = mid.context(String::from("top_owned"));

    assert_eq!(format!("{}", top), "top_owned");
    assert_eq!(format!("{:#}", top), "top_owned: mid_owned: leaf_owned");

    let dbg = format!("{:?}", top);
    assert!(dbg.contains("top_owned"));
    assert!(dbg.contains("mid_owned"));
    assert!(dbg.contains("leaf_owned"));
}

