fn test_error_from_boxed_and_context_preserves_chain() {
    use std::io;
    let boxed: Box<dyn StdError + Send + Sync> =
        Box::new(io::Error::new(io::ErrorKind::Other, "io_root"));
    let err = Error::from_boxed(boxed);
    let err = err.context("wrapped");

    assert_eq!(format!("{}", err), "wrapped");
    assert_eq!(format!("{:#}", err), "wrapped: io_root");
    assert_eq!(err.root_cause().to_string(), "io_root");
}
